```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = (select auth.uid())
      and tm.role = 'editor'
  );
$$;

revoke all on function public.is_team_member(bigint) from public, anon;
revoke all on function public.is_team_editor(bigint) from public, anon;
grant execute on function public.is_team_member(bigint) to authenticated, service_role;
grant execute on function public.is_team_editor(bigint) to authenticated, service_role;

-- R1: members can see their teams
create policy teams_select_member
  on public.teams
  for select
  to authenticated
  using (public.is_team_member(id));

-- R2: users can see only their own membership rows
create policy team_members_select_own
  on public.team_members
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R3: members can read non-deleted documents of their teams
create policy documents_select_member
  on public.documents
  for select
  to authenticated
  using (deleted_at is null and public.is_team_member(team_id));

-- R4: editors can create documents in their teams, as themselves
create policy documents_insert_editor
  on public.documents
  for insert
  to authenticated
  with check (
    created_by = (select auth.uid())
    and deleted_at is null
    and public.is_team_editor(team_id)
  );

-- R5: editors can edit documents in their teams; result must stay in a team they edit
create policy documents_update_editor
  on public.documents
  for update
  to authenticated
  using (deleted_at is null and public.is_team_editor(team_id))
  with check (deleted_at is null and public.is_team_editor(team_id));

-- R6: only the creator can soft-delete (set deleted_at) a document
create policy documents_softdelete_creator
  on public.documents
  for update
  to authenticated
  using (deleted_at is null and created_by = (select auth.uid()))
  with check (deleted_at is not null and created_by = (select auth.uid()));

-- R6: only the creator can hard-delete a document
create policy documents_delete_creator
  on public.documents
  for delete
  to authenticated
  using (deleted_at is null and created_by = (select auth.uid()));

-- R7: no insert/update/delete policies on teams or team_members => denied for app users

-- R8: anonymous visitors get nothing
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;
revoke all on sequence public.documents_id_seq from anon;

-- R9: service role keeps full access
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;
grant all on sequence public.documents_id_seq to service_role;

grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;
grant usage on sequence public.documents_id_seq to authenticated;
```

