-- Helper functions (security definer so they can read team_members without RLS recursion)
create or replace function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id and user_id = auth.uid()
  );
$$;

create or replace function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id and user_id = auth.uid() and role = 'editor'
  );
$$;

revoke all on function public.is_team_member(bigint) from public, anon;
revoke all on function public.is_team_editor(bigint) from public, anon;
grant execute on function public.is_team_member(bigint) to authenticated, service_role;
grant execute on function public.is_team_editor(bigint) to authenticated, service_role;

-- Trigger: created_by is immutable, and only the creator may soft-delete a document
create or replace function public.documents_before_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.created_by is distinct from old.created_by then
    raise exception 'created_by is immutable' using errcode = '42501';
  end if;

  if old.deleted_at is null and new.deleted_at is not null
     and auth.uid() is not null
     and new.created_by <> auth.uid() then
    raise exception 'only the creator can delete a document' using errcode = '42501';
  end if;

  return new;
end;
$$;

revoke all on function public.documents_before_update() from public, anon;

create trigger documents_before_update_trg
before update on public.documents
for each row execute function public.documents_before_update();

-- Enable RLS
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- R1: users see the teams they belong to
create policy teams_select_member
on public.teams
for select
to authenticated
using (public.is_team_member(id));

-- R2: users see only their own membership rows
create policy team_members_select_own
on public.team_members
for select
to authenticated
using (user_id = (select auth.uid()));

-- R3: members read non-deleted documents of their teams
create policy documents_select_member
on public.documents
for select
to authenticated
using (deleted_at is null and public.is_team_member(team_id));

-- R4: editors create documents in their teams, recorded as themselves
create policy documents_insert_editor
on public.documents
for insert
to authenticated
with check (
  created_by = (select auth.uid())
  and public.is_team_editor(team_id)
);

-- R5 (+R6 soft-delete guard): editors update live documents in their teams;
-- the resulting row must still be in a team where the user is an editor, and
-- setting deleted_at is only permitted for the creator.
create policy documents_update_editor
on public.documents
for update
to authenticated
using (
  deleted_at is null
  and public.is_team_editor(team_id)
)
with check (
  public.is_team_editor(team_id)
  and (deleted_at is null or created_by = (select auth.uid()))
);

-- R6: only the creator can hard-delete a document
create policy documents_delete_creator
on public.documents
for delete
to authenticated
using (created_by = (select auth.uid()));

-- R7: teams and memberships are read-only for app users (no insert/update/delete policies)
-- R8: anonymous visitors get nothing

revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;

revoke insert, update, delete on public.teams from authenticated;
revoke insert, update, delete on public.team_members from authenticated;

grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

grant usage, select on all sequences in schema public to authenticated;

-- R9: service role keeps full access
grant all on public.teams to service_role;
grant all on public.team_members to service_role;
grant all on public.documents to service_role;
grant usage, select on all sequences in schema public to service_role;
