      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- Safely resolve the org that owns a storage path of the form '<project id>/<file>'
create or replace function public.project_org_id(p_path text)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select p.org_id
  from public.projects p
  where p.id = case
                 when split_part(p_path, '/', 1) ~ '^[0-9]+$'
                   then split_part(p_path, '/', 1)::bigint
                 else null
               end;
$$;

