alter table public.posts enable row level security;
alter table public.comments enable row level security;

-- Helper: is a post live (published in the past, not yet unpublished)?
create or replace function public.post_is_live(
  p_published_at timestamptz,
  p_unpublish_at timestamptz
)
returns boolean
language sql
stable
as $$
  select p_published_at is not null
     and p_published_at <= now()
     and (p_unpublish_at is null or p_unpublish_at > now());
$$;

-- Helper: can the current user read the given post? (mirrors posts SELECT policy)
create or replace function public.can_read_post(p_post_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.posts p
    where p.id = p_post_id
      and (
        public.post_is_live(p.published_at, p.unpublish_at)
        or p.author_id = auth.uid()
      )
  );
$$;

-- Helper: is the current user the author of the given post?
create or replace function public.is_post_author(p_post_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.posts p
    where p.id = p_post_id
      and p.author_id = auth.uid()
  );
$$;

-- R1 + R2: anyone can read live posts; authors can read all of their own posts.
create policy posts_select_live_or_own
  on public.posts
  for select
  to anon, authenticated
  using (
    public.post_is_live(published_at, unpublish_at)
    or author_id = auth.uid()
  );

-- R3 + R7: signed-in users may only insert posts authored by themselves.
create policy posts_insert_self
  on public.posts
  for insert
  to authenticated
  with check (author_id = auth.uid());

-- R3: authors may edit their own posts and may not hand them to another author.
create policy posts_update_own
  on public.posts
  for update
  to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

-- R3: authors may delete their own posts.
create policy posts_delete_own
  on public.posts
  for delete
  to authenticated
  using (author_id = auth.uid());

-- R4: a comment is visible exactly to those who can read its post.
create policy comments_select_readable_post
  on public.comments
  for select
  to anon, authenticated
  using (public.can_read_post(post_id));

-- R5 + R7: signed-in users may comment as themselves on posts they can read.
create policy comments_insert_self
  on public.comments
  for insert
  to authenticated
  with check (
    author_id = auth.uid()
    and public.can_read_post(post_id)
  );

-- R6: comment authors may delete their own comments; post authors may delete any
-- comment on their posts. No UPDATE policy exists, so comments are immutable.
create policy comments_delete_own_or_post_author
  on public.comments
  for delete
  to authenticated
  using (
    author_id = auth.uid()
    or public.is_post_author(post_id)
  );

-- Privileges: anon is read-only.
revoke all on public.posts from anon;
revoke all on public.comments from anon;
grant select on public.posts to anon;
grant select on public.comments to anon;

-- Privileges: authenticated users get the operations the policies allow.
grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, delete on public.comments to authenticated;
revoke update on public.comments from authenticated;
grant usage, select on sequence public.comments_id_seq to authenticated;

-- R8: service role keeps full access.
grant all on public.posts to service_role;
grant all on public.comments to service_role;
grant usage, select on sequence public.comments_id_seq to service_role;

-- Lock down helper function execution.
revoke execute on function public.post_is_live(timestamptz, timestamptz) from public;
revoke execute on function public.can_read_post(bigint) from public;
revoke execute on function public.is_post_author(bigint) from public;

grant execute on function public.post_is_live(timestamptz, timestamptz) to anon, authenticated, service_role;
grant execute on function public.can_read_post(bigint) to anon, authenticated, service_role;
grant execute on function public.is_post_author(bigint) to authenticated, service_role;
