-- Helper: is the current user an active (non-suspended) account?
create or replace function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not coalesce(
    (select a.suspended from public.accounts a where a.user_id = auth.uid()),
    false
  );
$$;

-- Helper: does uid own file fid? (security definer to avoid RLS recursion)
create or replace function public.is_file_owner(fid bigint, uid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.files f
    where f.id = fid and f.owner_id = uid
  );
$$;

-- Helper: does uid have a live share on file fid (optionally requiring edit)?
create or replace function public.has_shared_access(fid bigint, uid uuid, need_edit boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.file_shares s
    where s.file_id = fid
      and s.shared_with = uid
      and (s.expires_at is null or s.expires_at > now())
      and (not need_edit or s.can_edit)
  );
$$;

-- Helper: prevent changing a file's owner through the app
create or replace function public.prevent_file_owner_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id is distinct from old.owner_id and auth.uid() is not null then
    raise exception 'file owner cannot be changed';
  end if;
  return new;
end;
$$;

create trigger files_prevent_owner_change
