-- ---------------------------------------------------------------------------
-- Guard: status / decided_by may only change through decide_expense(),
-- and identity columns of an expense are immutable.
-- ---------------------------------------------------------------------------
create or replace function public.expenses_guard_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.id is distinct from old.id
     or new.department_id is distinct from old.department_id
     or new.submitted_by is distinct from old.submitted_by then
    raise exception 'expense id, department_id and submitted_by are immutable'
      using errcode = '42501';
  end if;

  if new.status is distinct from old.status
     or new.decided_by is distinct from old.decided_by then
    if coalesce(current_setting('app.expense_decision', true), '') <> 'on' then
      raise exception 'status and decided_by can only be changed via decide_expense()'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

revoke all on function public.expenses_guard_update() from public;

