-- ---------------------------------------------------------------------------
-- decide_expense
-- ---------------------------------------------------------------------------
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_is_service_role boolean :=
    coalesce(auth.role(), (auth.jwt() ->> 'role'), '') = 'service_role';
  v_expense public.expenses;
  v_new_status text := case when p_approve then 'approved' else 'rejected' end;
begin
  select *
    into v_expense
    from public.expenses e
   where e.id = p_expense_id
     for update;

  if not found then
    raise exception 'expense % not found', p_expense_id using errcode = 'P0002';
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense % is not pending', p_expense_id using errcode = 'P0001';
  end if;

  -- R5: service role may decide any pending expense; decided_by stays empty.
  if v_is_service_role then
    perform set_config('app.expense_decision', 'on', true);
    update public.expenses
       set status = v_new_status,
           decided_by = null
     where id = p_expense_id;
    return;
  end if;

  if v_uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if v_expense.submitted_by = v_uid then
    raise exception 'you cannot decide your own expense' using errcode = '42501';
  end if;

  if not exists (
    select 1
      from public.department_members m
     where m.department_id = v_expense.department_id
       and m.user_id = v_uid
       and m.is_manager
  ) then
    raise exception 'you are not a manager of department %', v_expense.department_id
      using errcode = '42501';
  end if;

  perform set_config('app.expense_decision', 'on', true);
  update public.expenses
     set status = v_new_status,
         decided_by = v_uid
   where id = p_expense_id;
end;
$$;

revoke all on function public.decide_expense(bigint, boolean) from public;
grant execute on function public.decide_expense(bigint, boolean) to authenticated, service_role;

