-- Helper: guard against direct changes to decision columns / immutable columns
create or replace function public.expenses_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Service role keeps full table access (R8).
  if auth.role() = 'service_role' then
    return new;
  end if;

  -- Only public.decide_expense() may flip the decision columns (R3).
  if coalesce(current_setting('expenses.decision', true), 'off') = 'on' then
    return new;
  end if;

  if new.status is distinct from old.status then
    raise exception 'status cannot be changed directly' using errcode = '42501';
  end if;

  if new.decided_by is distinct from old.decided_by then
    raise exception 'decided_by cannot be changed directly' using errcode = '42501';
  end if;

  if new.submitted_by is distinct from old.submitted_by then
    raise exception 'submitted_by cannot be changed' using errcode = '42501';
  end if;

  if new.department_id is distinct from old.department_id then
    raise exception 'department_id cannot be changed' using errcode = '42501';
  end if;

  if new.id is distinct from old.id then
    raise exception 'id cannot be changed' using errcode = '42501';
  end if;

  return new;
end;
$$;

revoke execute on function public.expenses_guard() from public, anon, authenticated;

create trigger expenses_guard
before update on public.expenses
for each row execute function public.expenses_guard();

-- Decision entry point (R4, R5, R7)
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_exp public.expenses%rowtype;
  v_uid uuid := auth.uid();
  v_role text := auth.role();
begin
  select *
    into v_exp
    from public.expenses
   where id = p_expense_id
   for update;

  if not found then
    raise exception 'expense % not found', p_expense_id using errcode = 'P0002';
  end if;

  if v_exp.status <> 'pending' then
    raise exception 'expense % is not pending', p_expense_id using errcode = 'P0001';
  end if;

  -- Service role: any pending expense, decided_by left empty (R5).
  if v_role = 'service_role' then
    perform set_config('expenses.decision', 'on', true);
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end
     where id = p_expense_id;
    perform set_config('expenses.decision', 'off', true);
    return;
  end if;

  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if v_exp.submitted_by = v_uid then
    raise exception 'submitters cannot decide their own expense' using errcode = '42501';
  end if;

  if not exists (
    select 1
      from public.department_members m
     where m.department_id = v_exp.department_id
       and m.user_id = v_uid
       and m.is_manager
  ) then
    raise exception 'caller does not manage department %', v_exp.department_id using errcode = '42501';
  end if;

  perform set_config('expenses.decision', 'on', true);
  update public.expenses
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = v_uid
   where id = p_expense_id;
  perform set_config('expenses.decision', 'off', true);
end;
$$;

