create or replace function public.decide_expense(
  p_expense_id bigint,
  p_approve boolean
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid        uuid := auth.uid();
  v_jwt_role   text := coalesce(auth.role(), '');
  v_session_role text := coalesce(current_setting('role', true), 'none');
  v_is_service boolean;
  v_expense    public.expenses;
begin
  -- Service / trusted server-side context detection.
  v_is_service :=
    v_jwt_role = 'service_role'
    or v_session_role = 'service_role'
    or (
      v_jwt_role = ''
      and v_session_role in ('none', '')
      and v_uid is null
    );

  if p_expense_id is null then
    raise exception 'expense id is required' using errcode = '22023';
  end if;

  select *
    into v_expense
    from public.expenses
   where id = p_expense_id
     for update;

  if not found then
    raise exception 'expense % does not exist', p_expense_id using errcode = 'P0002';
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense % is not pending (status: %)', p_expense_id, v_expense.status
      using errcode = 'P0001';
  end if;

  if v_is_service then
    -- Service role: allowed on any pending expense; decided_by stays empty.
    perform set_config('app.decide_expense', 'on', true);
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end,
           decided_by = null
     where id = p_expense_id;
    perform set_config('app.decide_expense', 'off', true);
    return;
  end if;

  if v_uid is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;

  if not public.is_department_manager(v_expense.department_id, v_uid) then
    raise exception 'caller does not manage department %', v_expense.department_id
      using errcode = '42501';
  end if;

  if v_expense.submitted_by = v_uid then
    raise exception 'submitter cannot decide their own expense' using errcode = '42501';
  end if;

  perform set_config('app.decide_expense', 'on', true);
  update public.expenses
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = v_uid
   where id = p_expense_id;
  perform set_config('app.decide_expense', 'off', true);
end;
$$;

