-- Helper: is the current request user finance staff?
-- SECURITY DEFINER so it can read finance_staff without recursing through its own RLS.
create or replace function public.is_finance_staff()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.finance_staff fs
    where fs.user_id = (select auth.uid())
  );
$$;

