grant execute on function public.is_finance_staff() to authenticated, service_role;

-- R7: a user may see only their own finance_staff row; no write policies exist,
-- so finance_staff is read-only through the API.
create policy finance_staff_select_self
on public.finance_staff
for select
to authenticated
using (user_id = (select auth.uid()));

-- R1: creators read their own invoices; finance staff read everything.
create policy invoices_select_own_or_finance
on public.invoices
for select
to authenticated
using (
  created_by = (select auth.uid())
  or public.is_finance_staff()
);

-- R2: insert only as yourself and only as a draft.
create policy invoices_insert_own_draft
on public.invoices
for insert
to authenticated
with check (
  created_by = (select auth.uid())
  and status = 'draft'
);

-- R3 / R4: creators may touch their own drafts; finance staff may touch sent invoices.
create policy invoices_update_creator_draft_or_finance_sent
on public.invoices
for update
to authenticated
using (
  (created_by = (select auth.uid()) and status = 'draft')
  or (public.is_finance_staff() and status = 'sent')
)
with check (
  (created_by = (select auth.uid()) and status in ('draft', 'sent'))
  or (public.is_finance_staff() and status in ('sent', 'paid', 'void'))
);

-- R5: only the creator may delete, and only while the invoice is a draft.
create policy invoices_delete_own_draft
on public.invoices
for delete
to authenticated
using (
  created_by = (select auth.uid())
  and status = 'draft'
);

-- Field-level immutability and status-transition enforcement.
-- R6: created_by never changes.
-- R3: customer/amount editable only while the invoice is a draft.
-- R3/R4: only draft -> sent (creator) and sent -> paid|void (finance staff) are valid.
-- R9: service_role (and non-API connections) bypass the business rules.
create or replace function public.invoices_enforce_transitions()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if coalesce(auth.role(), 'service_role') = 'service_role' then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'invoices.created_by is immutable' using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'sent' then
      if old.created_by is distinct from (select auth.uid()) then
        raise exception 'only the creator may send a draft invoice' using errcode = '42501';
      end if;
    elsif old.status = 'sent' and new.status in ('paid', 'void') then
      if not public.is_finance_staff() then
        raise exception 'only finance staff may settle an invoice' using errcode = '42501';
      end if;
    else
      raise exception 'invalid invoice status transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;
  end if;

  if new.customer is distinct from old.customer
     or new.amount is distinct from old.amount then
    if old.status <> 'draft' then
      raise exception 'customer and amount are immutable once an invoice leaves draft'
        using errcode = '42501';
    end if;
    if new.status not in ('draft', 'sent') then
      raise exception 'invalid invoice status transition: % -> %', old.status, new.status
        using errcode = '42501';
    end if;
    if old.created_by is distinct from (select auth.uid()) then
      raise exception 'only the creator may edit a draft invoice' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

create trigger invoices_enforce_transitions
before update on public.invoices
for each row
execute function public.invoices_enforce_transitions();

grant select on public.finance_staff to authenticated;
grant select, insert, update, delete on public.invoices to authenticated;
grant usage on sequence public.invoices_id_seq to authenticated;
